// Unmodified source-host transactions, including complete adapter replies and calls.
import fs from 'node:fs';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
const cases=[];
const specs={};for(const action of ['set','add-macro','remove-macro','randomize-macros','insert-chain','copy-pad','store-variation','recall-variation','delete-variation'])specs[action]={method:'Rack',tool:'rack',args:{action,rackRef:'device:utility-1',...(action==='set'?{selectedVariationIndex:0}:{}),...(action==='copy-pad'?{sourceIndex:36,targetIndex:37}:{}),...(['recall-variation','delete-variation'].includes(action)?{index:0}:{})}};specs.view={method:'RackView',tool:'rack_view',args:{rackRef:'device:utility-1',selectedChainRef:'chain:rack-1:0',selectedPadIndex:36,padScrollPosition:4,showChainDevices:false}};specs['view-null']={method:'RackView',tool:'rack_view',args:{rackRef:'device:utility-1',selectedChainRef:null,selectedPadIndex:-1}};

function clean(value){if(value===undefined)return null;value=structuredClone(value);if(value?.result?.content?.[0]?.text)try{value.result.content[0].text=JSON.parse(value.result.content[0].text)}catch{}function walk(v,key){if(typeof v==='string'&&/^(rack|rackview)_/.test(v))return '$transaction';if(key==='expiresAt'&&v!==0)return '$time';if(Array.isArray(v))return v.map(w=>walk(w));if(v&&typeof v==='object')return Object.fromEntries(Object.entries(v).map(([k,w])=>[k,walk(w,k)]));return v;}return walk(value);}
function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null;}
async function make(kind,scenario,args=specs[kind].args,previewOnly=false){const spec=specs[kind],sim=new DeterministicLiveSimulator(),calls=[],cache=new Map();let fault='',fired=false,after=false;
 const track=sim.state.tracks[0],device=track.devices[0];device.kind='rack';device.canHaveChains=true;device.canHaveDrumPads=true;device.chains=[{ref:'chain:rack-1:0',parentRef:device.ref,objectIdentity:'simulator:chain:rack-1:0',index:0,name:'Chain 1',mute:false,solo:false,devices:[],colorIndex:5,autoColor:false}];device.drumPads=[{ref:'drum-pad:rack-1:0',parentRef:device.ref,index:36,name:'Pad 1',mute:false,chains:[],note:36,solo:false,objectIdentity:'simulator:drum-pad:rack-1:0'},{ref:'drum-pad:rack-1:1',parentRef:device.ref,index:37,name:'Pad 2',mute:false,chains:[],note:37,solo:false,objectIdentity:'simulator:drum-pad:rack-1:1'}];device.macros=[{ref:'parameter:macro-1',objectIdentity:'simulator:parameter:macro-1',name:'Macro 1',value:0}];device.macroMapped=[true];device.visibleMacroCount=8;device.variationCount=1;device.selectedVariationIndex=0;device.rackView={padScrollPosition:0,showChainDevices:true,selectedChainRef:null,selectedPadIndex:null};const object=device;
 if(scenario==='missing-identity')delete device.objectIdentity;if(scenario==='not-rack')device.canHaveChains=false;if(scenario==='missing-view')delete device.rackView;if(scenario==='missing-macro-identity')delete device.macros[0].objectIdentity;if(scenario==='missing-chain-identity')delete device.chains[0].objectIdentity;if(scenario==='missing-pad-identity')delete device.drumPads[0].objectIdentity;
 function status(){const s=sim.status();if(scenario==='disconnected')s.connected=false;if(scenario==='no-capability')s.capabilities=[];if(scenario==='no-operation')s.operations=[];return s;}
 function readFault(){if(!fired&&(fault.endsWith('current-read')||fault.endsWith('-read')&&after)){fired=true;throw Error('injected authoritative read failure');}}
 async function capture(method,args,ctx,work){const row={method,args:clean(args),context:clean(context(ctx))};calls.push(row);try{const value=await work();row.result=clean(value);return value}catch(error){row.error={message:error.message,kind:error instanceof LiveMutationNotDispatchedError?'not-dispatched':'error'};throw error}}
 function invoke(i,c){const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(cache.has(key))return structuredClone(cache.get(key));if(!fired&&['before','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error('injected operation failure')}if(!fired&&fault.endsWith('null')){fired=true;return null}const noEffect=!fired&&fault.endsWith('no-effect');const result=noEffect?{ok:true}:sim.invoke(i);if(noEffect)fired=true;else cache.set(key,structuredClone(result));after=true;if(!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure')}if(!fired&&fault==='apply-postcondition'){fired=true;device.selectedVariationIndex=99}return result;}
 const adapter={status,snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>sim.invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),refreshStatusAsync:c=>capture('status',null,c,()=>status()),snapshotAsync:(c,r)=>capture('snapshot',r??null,c,()=>{readFault();return sim.snapshotAsync(c,r)}),discoverAsync:(r,c)=>capture('discover',r,c,()=>{readFault();return sim.discoverAsync(r,c)}),getAsync:(r,c)=>capture('get',r,c,()=>{readFault();return sim.get(r)}),invokeAsync:(i,c)=>capture('invoke',i,c,()=>invoke(i,c))};
 const host=new McpHost(adapter),steps=[];let txid;
 async function step(action,p,extra={}){const before=calls.length,input={action,args:clean(p),status:status(),...extra};let result;try{const signal=new AbortController();if(extra.abort)signal.abort();if(action==='undo')result=await host.liveUndoAsync(1,{...p,transactionId:txid},signal.signal);else result=await host['live'+spec.method+(action==='preview'?'Preview':'Apply')+'Async'](1,action==='preview'?p:{...p,transactionId:txid},signal.signal)}catch(error){result={throw:error.message}}if(action==='preview')try{txid=JSON.parse(result.result.content[0].text).transactionId}catch{}steps.push({...input,result:clean(result),record:clean(txid?host.clipLifecycleTransactions.get(txid):undefined),calls:calls.slice(before)})}
 await step('preview',args);if(txid&&!previewOnly){const t=host.clipLifecycleTransactions.get(txid);if(scenario==='expire')t.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='identity')object.objectIdentity='manual';if(scenario==='state'){device.selectedVariationIndex=99;device.rackView.padScrollPosition=99}
 if(scenario.startsWith('apply-'))fault=scenario;for(const[index,key]of['apply-key','other-key','apply-key'].entries())await step('apply',{confirmation:'apply',idempotencyKey:key},{...(scenario==='expire'&&index===0?{expire:true}:{}),...(scenario==='apply-preabort'?{abort:true}:{})});fault='';fired=false;after=false;
 if(scenario==='undo-epoch')sim.reconnect();if(scenario==='undo-identity')object.objectIdentity='manual';if(scenario==='undo-state'){device.selectedVariationIndex=99;device.rackView.padScrollPosition=99;device.visibleMacroCount=15}if(scenario==='undo-structure')device.chains.push({ref:'chain:later',parentRef:device.ref,index:1,mute:false,solo:false,objectIdentity:'later',name:'Later',devices:[]});
 if(scenario.startsWith('undo-')&&!['undo-epoch','undo-identity','undo-structure','undo-state'].includes(scenario))fault=scenario;for(const key of ['undo-key','other-undo-key','undo-key'])await step('undo',{confirmation:'undo',idempotencyKey:key});}
 cases.push({label:kind+' '+scenario,tool:spec.tool,steps});}
const scenarios=['normal','expire','epoch','identity','state','missing-identity','not-rack','missing-view','missing-macro-identity','missing-chain-identity','missing-pad-identity','disconnected','no-capability','no-operation','apply-before','apply-after','apply-refusal','apply-no-effect','apply-null','apply-read','apply-current-read','apply-preabort','apply-postcondition','undo-before','undo-after','undo-refusal','undo-no-effect','undo-null','undo-read','undo-current-read','undo-epoch','undo-identity','undo-state','undo-structure'];
for(const kind of Object.keys(specs)){for(const scenario of scenarios)await make(kind,scenario);const valid=specs[kind].args;for(const args of [null,[],{},false,0,'x',{...valid,extra:1}])await make(kind,'invalid '+JSON.stringify(args),args,true);for(const key of Object.keys(valid)){const omit={...valid};delete omit[key];await make(kind,'omitted '+key,omit,true);for(const value of [null,[],{},false,true,-1,0,0.5,2,9,'','a'.repeat(257)])await make(kind,'invalid '+key+' '+JSON.stringify(value),{...valid,[key]:value},true)}}
fs.writeFileSync(new URL('host-racks-oracle.json',import.meta.url),JSON.stringify({cases}));console.log({cases:cases.length,steps:cases.reduce((n,c)=>n+c.steps.length,0)});
